using System.IO.Compression;using System.Text.Json;
namespace Trial;
internal static class GameAssets
{
 static readonly object gate=new();static ZipArchive? archive;static readonly Dictionary<int,string> cache=new();
 public static string Icon(int id){if(id<=0)return "";lock(gate){if(cache.TryGetValue(id,out var value))return value;var file=Path.Combine(AppContext.BaseDirectory,"组件","game-icons.zip");if(!File.Exists(file))return "";archive??=ZipFile.OpenRead(file);var entry=archive.GetEntry(id+".png");if(entry==null||entry.Length>128*1024)return "";using var stream=entry.Open();using var bytes=new MemoryStream();stream.CopyTo(bytes);value="data:image/png;base64,"+Convert.ToBase64String(bytes.ToArray());if(cache.Count>=1024)cache.Clear();cache[id]=value;return value;}}
 public static object Icons(JsonElement root){var ids=root.GetProperty("ids").EnumerateArray().Select(x=>x.GetInt32()).Distinct().ToArray();if(ids.Length>12)throw new InvalidDataException("图标请求过多");var icons=ids.ToDictionary(i=>i.ToString(),Icon);return new{ok=true,icons=icons.Where(p=>p.Value.Length>0).ToDictionary(),failed=ids.Where(i=>icons[i.ToString()].Length==0).ToArray()};}
 public static object Display(string kind)=>kind=="jobs"?new{ok=true,jobIcons=Enumerable.Range(1,45).ToDictionary(i=>i.ToString(),i=>Icon(62100+i))}:(object)new{ok=true,statusIcons=new{},bitmapIcons=new{}};
 public static object Item(int id){var item=GameCatalog.Row("items",id)??throw new InvalidDataException("物品编号不存在");return new{ok=true,name=GameCatalog.Text(item,"name"),icon=Icon(GameCatalog.Number(item,"icon")),category=GameCatalog.Text(item,"category"),level=GameCatalog.Number(item,"level"),description=GameCatalog.Text(item,"description"),price=GameCatalog.Number(item,"price"),stackSize=GameCatalog.Number(item,"max")};}
}
internal sealed class RecruitmentAdapter(GameLink game)
{
 readonly SemaphoreSlim serial=new(1);readonly Dictionary<string,View> views=new();
 sealed class View{public string id=Guid.NewGuid().ToString("N"),cid="",detail="",listing="";public int area,category,page;public long refreshed;public JsonElement[] rows=[];public string warning="";}
 static string Str(JsonElement r,string k)=>r.TryGetProperty(k,out var v)?v.GetString()??"":"";
 async Task Refresh(View v,CancellationToken token){var result=JsonSerializer.SerializeToElement(await game.Recruitment(v.area,true,token));v.rows=result.GetProperty("rows").EnumerateArray().Select(x=>x.Clone()).ToArray();v.warning=Str(result,"warning");v.refreshed=Environment.TickCount64;}
 public async Task<object> Board(JsonElement r,string owner,CancellationToken token)
 {
  await serial.WaitAsync(token);try{string action=Str(r,"action");var who=game.Identity;if(!who.online)throw new IOException("请先连接已登录的角色");View? v;
   if(action=="open"){v=new(){cid=who.contentId};views[owner]=v;await Refresh(v,token);}else{if(!views.TryGetValue(owner,out v)||v.id!=Str(r,"viewId")||v.cid!=who.contentId)throw new IOException("招募页面已失效，请重新打开");int index=r.TryGetProperty("index",out var i)?i.GetInt32():0;
    switch(action){case "close":views.Remove(owner);return new{ok=true};case "refresh":v.page=0;await Refresh(v,token);break;case "area":if(index is <0 or >2)throw new InvalidDataException("招募地区无效");v.area=index;v.page=0;await Refresh(v,token);break;case "category":if(index is <0 or >16)throw new InvalidDataException("招募分类无效");v.category=index;v.page=0;break;case "next":v.page++;break;case "previous":v.page--;break;case "read":if(Environment.TickCount64-v.refreshed>=15000)await Refresh(v,token);break;default:throw new InvalidDataException("未知招募操作");}}
   if(v.cid!=game.Identity.contentId)throw new IOException("角色已切换，招募数据已丢弃");return Present(v);
  }finally{serial.Release();}
 }
 static bool Category(JsonElement r,int category)=>category==0||r.GetProperty("category").GetUInt32()==(category==16?0u:1u<<category);
 object Present(View v){var active=v.rows.Where(r=>r.GetProperty("expires").GetDateTimeOffset()>DateTimeOffset.UtcNow).ToArray();var rows=active.Where(r=>Category(r,v.category)).ToArray();v.page=Math.Clamp(v.page,0,Math.Max(0,(rows.Length-1)/20));var page=rows.Skip(v.page*20).Take(20).ToArray();return new{ok=true,open=true,source="game-network",warning=v.warning,viewId=v.id,rows=page.Select(Listing).ToArray(),categories=Enumerable.Range(0,17).Select(i=>new{index=i,label=active.Count(r=>Category(r,i)).ToString(),selected=v.category==i,nodes=Array.Empty<object>()}).ToArray(),area=v.area,areaCounts=Array.Empty<object>(),page=rows.Length==0?"0":$"{v.page*20+1}–{v.page*20+page.Length}",count=rows.Length.ToString(),canNext=(v.page+1)*20<rows.Length,canPrevious=v.page>0};}
 static object Listing(JsonElement row){int type=row.GetProperty("dutyType").GetInt32();var duty=type==1?GameCatalog.Row("roulettes",row.GetProperty("duty").GetInt32()):type==2?GameCatalog.Row("duties",row.GetProperty("duty").GetInt32()):null;var jobs=row.GetProperty("jobs").GetBytesFromBase64();int filled=row.GetProperty("filledSlots").GetInt32();return new{listingId=Str(row,"id"),category=row.GetProperty("category").GetUInt32(),duty=GameCatalog.Text(duty,"name") is {Length:>0} name?name:"无",dutyIcon=GameAssets.Icon(GameCatalog.Number(duty,"icon")),leader=Str(row,"leader"),leaderParts=Array.Empty<object>(),comment=Str(row,"comment"),commentParts=Array.Empty<object>(),itemLevel=row.GetProperty("itemLevel").GetInt32()==0?"无":row.GetProperty("itemLevel").ToString(),slots=Enumerable.Range(0,row.GetProperty("totalSlots").GetInt32()).Select(i=>new{filled=i<filled,job=i<jobs.Length?jobs[i]:0,role=i<jobs.Length?GameCatalog.Number(GameCatalog.Row("jobs",jobs[i]),"role"):0,flags="0"}).ToArray()};}
 public async Task<object> Detail(JsonElement r,string owner,CancellationToken token){await serial.WaitAsync(token);try{if(!views.TryGetValue(owner,out var v)||v.cid!=game.Identity.contentId)throw new IOException("请重新打开招募板");string action=Str(r,"action");if(action=="close"){v.detail=v.listing="";return new{ok=true};}if(action=="open"){if(v.id!=Str(r,"boardView"))throw new IOException("招募板已刷新");v.listing=Str(r,"listingId");v.detail=Guid.NewGuid().ToString("N");}else if(v.detail!=Str(r,"viewId"))throw new IOException("招募详情已失效");var row=v.rows.SingleOrDefault(row=>Str(row,"id")==v.listing);if(row.ValueKind==JsonValueKind.Undefined||row.GetProperty("expires").GetDateTimeOffset()<=DateTimeOffset.UtcNow)throw new IOException("该招募已过期，请刷新");if(action is "join" or "tell"||action.StartsWith("join:")){
    using(var reader=new CharacterReader(game.Identity)){if(reader.Confirmation()!=null)throw new IOException("请先处理游戏中已有的确认窗口");}
    await game.NativeAction("listing:"+v.listing,v.cid,token);bool ready=false;for(int i=0;i<40;i++){using var reader=new CharacterReader(game.Identity);if(reader.Addon("LookingForGroupDetail")!=null){ready=true;break;}await Task.Delay(200,token);}if(!ready)throw new IOException("游戏招募详情未就绪，请刷新");await game.NativeAction("recruit:"+action,v.cid,token);await Task.Delay(200,token);
   }else if(action is "confirm-yes" or "confirm-no"){
    using var reader=new CharacterReader(game.Identity);var confirm=reader.Confirmation()??throw new IOException("招募确认窗口已改变");if(!confirm.prompt.Contains(Str(row,"leader"))&&!confirm.prompt.Contains("参加")&&!confirm.prompt.Contains("密码"))throw new IOException("当前不是这条招募的确认窗口");await game.NativeAction($"confirm:{(action=="confirm-yes"?1:0)}:{confirm.id}",v.cid,token);
   }else if(action is not ("open" or "refresh"))throw new InvalidDataException("未知招募操作");
   using var currentReader=new CharacterReader(game.Identity);var confirmation=currentReader.Confirmation();
   var shown=JsonSerializer.SerializeToElement(Listing(row));string world=GameNames.World(row.GetProperty("homeWorld").ToString());return new{ok=true,open=true,source="game-network",viewId=v.detail,listingId=v.listing,leader=shown.GetProperty("leader"),leaderParts=Array.Empty<object>(),duty=shown.GetProperty("duty"),dutyIcon=shown.GetProperty("dutyIcon"),comment=shown.GetProperty("comment"),commentParts=Array.Empty<object>(),location=world,timeLeft=$"剩余{Math.Max(0,(int)(row.GetProperty("expires").GetDateTimeOffset()-DateTimeOffset.UtcNow).TotalMinutes)}分",itemLevel=shown.GetProperty("itemLevel"),status="",confirmation=confirmation.HasValue?new{prompt=confirmation.Value.prompt,addonId=confirmation.Value.id}:null,slots=shown.GetProperty("slots"),tellTarget=Str(row,"leader")+"@"+world,canTell=world.Length>0,canJoin=row.GetProperty("filledSlots").GetInt32()<row.GetProperty("totalSlots").GetInt32()};}finally{serial.Release();}}
}
